import{_ as o,o as t,c as a,a3 as i}from"./chunks/framework.C6m_RRf-.js";const u=JSON.parse('{"title":"Update","description":"","frontmatter":{},"headers":[],"relativePath":"en/update.md","filePath":"en/update.md","lastUpdated":1789921234000}'),n={name:"en/update.md"};function s(l,e,d,c,r,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h1><p>The update procedure depends on how Twikoo was deployed. After updating the backend, remember to update the <code>x.x.x</code> version number in the frontend CDN URL so that both sides match, then redeploy your site.</p><h2 id="cloudbase-one-click-deployment" tabindex="-1">CloudBase, one-click deployment <a class="header-anchor" href="#cloudbase-one-click-deployment" aria-label="Permalink to &quot;CloudBase, one-click deployment&quot;">​</a></h2><p>Open 环境 → 我的应用 in the CloudBase console and enter:</p><ul><li>Source: <code>https://github.com/twikoojs/twikoo/tree/main</code></li><li>Branch: <code>main</code></li></ul><p>Leave the application directory empty and confirm; the deployment runs automatically.</p><div class="tip custom-block"><p class="custom-block-title">No version number to change</p><p>The one-click deployment depends on <code>twikoo-func@latest</code> (see <a href="https://github.com/twikoojs/twikoo/blob/main/templates/cloudbase/twikoo/package.json" target="_blank" rel="noreferrer"><code>templates/cloudbase/twikoo/package.json</code></a>), so a single redeploy picks up the newest stable release.</p><p>If the version does not change after redeploying, open 环境 → 云函数，open <code>package.json</code> and click <strong>保存并安装依赖</strong> once to force a fresh install.</p></div><h2 id="cloudbase-manual-deployment" tabindex="-1">CloudBase, manual deployment <a class="header-anchor" href="#cloudbase-manual-deployment" aria-label="Permalink to &quot;CloudBase, manual deployment&quot;">​</a></h2><p>Open 环境 → 云函数 in the CloudBase console, click the <code>twikoo</code> function, open the code editor, check that <code>package.json</code> depends on <code>&quot;twikoo-func&quot;: &quot;latest&quot;</code> (1.x pinned an exact version here — switching it to <code>latest</code> means you never have to edit it again), then click <strong>保存并安装依赖</strong> (save and install dependencies).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If your function is older than 1.0.0, recreate it following the manual deployment guide first (the deployment steps changed in 1.0.0).</p><p>If the comment list stops loading after an upgrade, delete the <code>node_modules</code> directory in the function editor (this takes about 30 seconds), then save and install dependencies again. If that does not help, delete and recreate the Twikoo function.</p></div><h2 id="cloudbase-command-line-deployment" tabindex="-1">CloudBase, command line deployment <a class="header-anchor" href="#cloudbase-command-line-deployment" aria-label="Permalink to &quot;CloudBase, command line deployment&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Removed in 2.0</p><p>Twikoo 2.0 removes command line deployment (<code>tcb fn deploy</code> and the <code>yarn deploy</code> / <code>login</code> / <code>logout</code> scripts). Use the console procedure above instead. The command below is kept for 1.x reference only.</p></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-env-id</span></span></code></pre></div><h2 id="vercel" tabindex="-1">Vercel <a class="header-anchor" href="#vercel" aria-label="Permalink to &quot;Vercel&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">No version number to change</p><p>The one-click deployment depends on <code>twikoo-vercel@latest</code> (see <a href="https://github.com/twikoojs/twikoo/blob/main/templates/vercel-min/package.json" target="_blank" rel="noreferrer"><code>templates/vercel-min/package.json</code></a>), so a redeploy picks up the newest stable release.</p><p>Vercel reuses the build cache by default, and a cache hit means <code>latest</code> is not re-resolved — <strong>clear the &quot;Use existing Build Cache&quot; checkbox when redeploying</strong>, otherwise the old dependency is kept.</p></div><ol><li>Open the <a href="https://vercel.com/dashboard" target="_blank" rel="noreferrer">Vercel dashboard</a> → twikoo → Deployments.</li><li>Open the menu (three dots) of the latest deployment → Redeploy.</li><li>Uncheck <strong>Use existing Build Cache</strong> and confirm.</li><li>Once deployed, open your domain: if the environment is configured correctly you should see &quot;Twikoo 云函数运行正常&quot;.</li></ol><h2 id="railway-and-zeabur" tabindex="-1">Railway and Zeabur <a class="header-anchor" href="#railway-and-zeabur" aria-label="Permalink to &quot;Railway and Zeabur&quot;">​</a></h2><p>The template repository <a href="https://github.com/twikoojs/twikoo-zeabur" target="_blank" rel="noreferrer"><code>twikoojs/twikoo-zeabur</code></a> depends on <code>tkserver@latest</code>, so <strong>there is no version number to change</strong>.</p><ol><li>On GitHub, open the <code>twikoo-zeabur</code> repository you forked and click <strong>Sync fork</strong>.</li><li>The deployment is triggered automatically; if it is not, or the version does not change, redeploy manually from the Railway / Zeabur dashboard.</li></ol><div class="tip custom-block"><p class="custom-block-title">If your fork pins an exact version</p><p>Change <code>&quot;tkserver&quot;: &quot;x.x.x&quot;</code> to <code>&quot;tkserver&quot;: &quot;latest&quot;</code> in <code>package.json</code> — from then on you only need to sync the fork and redeploy.</p></div><h2 id="netlify" tabindex="-1">Netlify <a class="header-anchor" href="#netlify" aria-label="Permalink to &quot;Netlify&quot;">​</a></h2><ol><li>On GitHub, open the <code>twikoo-netlify</code> repository you forked.</li><li>Check that <code>package.json</code> depends on <code>latest</code> (change it to the following if not):</li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;twikoo-netlify&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;latest&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Only one dependency since 2.0</p><p>1.x&#39;s <code>twikoo-netlify</code> reused the <code>twikoo-vercel</code> implementation, so both had to be listed. Since 2.0 they are independent implementations — <code>twikoo-netlify</code> alone is enough.</p></div><ol start="3"><li>Click <strong>Sync fork</strong>, then in the Netlify dashboard go to Deploys → Trigger deploy → <strong>Clear cache and deploy site</strong> (clearing the cache is what makes <code>latest</code> resolve again).</li><li>The deployment runs automatically.</li></ol><h2 id="hugging-face" tabindex="-1">Hugging Face <a class="header-anchor" href="#hugging-face" aria-label="Permalink to &quot;Hugging Face&quot;">​</a></h2><ol><li>Open your Space, click <strong>Settings</strong> in the top bar, scroll down and click <strong>Factory rebuild</strong>.</li></ol><h2 id="self-hosted-node" tabindex="-1">Self-hosted (Node) <a class="header-anchor" href="#self-hosted-node" aria-label="Permalink to &quot;Self-hosted (Node)&quot;">​</a></h2><ol><li>Stop the old version: <code>kill $(ps -ef | grep tkserver | grep -v &#39;grep&#39; | awk &#39;{print $2}&#39;)</code></li><li>Install the new version: <code>npm i -g tkserver@latest</code></li><li>Start it again: <code>nohup tkserver &gt;&gt; tkserver.log 2&gt;&amp;1 &amp;</code></li></ol><h2 id="self-hosted-docker" tabindex="-1">Self-hosted (Docker) <a class="header-anchor" href="#self-hosted-docker" aria-label="Permalink to &quot;Self-hosted (Docker)&quot;">​</a></h2><ol><li>Pull the new image: <code>docker pull imaegoo/twikoo</code></li><li>Stop the old container: <code>docker stop twikoo</code></li><li>Remove the old container: <code>docker rm twikoo</code></li><li>Start a new container (see the self-hosted Docker guide in the Chinese documentation).</li></ol><h2 id="automatic-updates" tabindex="-1">Automatic updates <a class="header-anchor" href="#automatic-updates" aria-label="Permalink to &quot;Automatic updates&quot;">​</a></h2><p>For availability and security reasons Twikoo does not implement automatic updates, and there is no plan to do so. If you want automatic updates, see <a href="https://github.com/MHuiG/twikoo-update" target="_blank" rel="noreferrer">twikoo-update</a> by MHuiG, which is built on GitHub workflows.</p>`,33)])])}const k=o(n,[["render",s]]);export{u as __pageData,k as default};
